from z3 import *

def solve():
    n = 20
    E = [[Bool(f"e_{i}_{j}") if i < j else None for j in range(n)] for i in range(n)]

    def edge(i, j):
        if i > j: i, j = j, i
        return E[i][j]

    s = Solver()

    # At least 37 edges
    edge_vars = [E[i][j] for i in range(n) for j in range(i+1, n)]
    s.add(PbGe([(e, 1) for e in edge_vars], 37))

    # No cycles of length 3
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                s.add(Not(And(edge(i,j), edge(j,k), edge(k,i))))

    # No cycles of length 4
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                for l in range(k+1, n):
                    # 3 possible 4-cycles on 4 vertices
                    s.add(Not(And(edge(i,j), edge(j,k), edge(k,l), edge(l,i))))
                    s.add(Not(And(edge(i,j), edge(j,l), edge(l,k), edge(k,i))))
                    s.add(Not(And(edge(i,k), edge(k,j), edge(j,l), edge(l,i))))

    # No cycles of length 5
    import itertools
    for c in itertools.combinations(range(n), 5):
        for p in itertools.permutations(c):
            # To avoid duplicates, only consider permutations where p[0] is min, and p[1] < p[4]
            if p[0] == min(p) and p[1] < p[4]:
                s.add(Not(And(edge(p[0],p[1]), edge(p[1],p[2]), edge(p[2],p[3]), edge(p[3],p[4]), edge(p[4],p[0]))))

    # No cycles of length 6
    for c in itertools.combinations(range(n), 6):
        for p in itertools.permutations(c):
            if p[0] == min(p) and p[1] < p[5]:
                s.add(Not(And(edge(p[0],p[1]), edge(p[1],p[2]), edge(p[2],p[3]), edge(p[3],p[4]), edge(p[4],p[5]), edge(p[5],p[0]))))

    # 4-colorable
    C = [Int(f"c_{i}") for i in range(n)]
    for i in range(n):
        s.add(C[i] >= 0, C[i] <= 3)
    for i in range(n):
        for j in range(i+1, n):
            s.add(Implies(edge(i,j), C[i] != C[j]))

    print("Solving...")
    if s.check() == sat:
        m = s.model()
        edges = []
        for i in range(n):
            for j in range(i+1, n):
                if is_true(m[E[i][j]]):
                    edges.append((i, j))
        print("SAT")
        print(edges)
    else:
        print("UNSAT")

solve()

from pysat.solvers import Glucose4
from pysat.card import CardEnc, EncType
import itertools

def solve():
    n = 20

    def edge_var(u, v):
        if u > v: u, v = v, u
        return u * n + v + 1

    solver = Glucose4()

    # No cycles of length 3
    for c in itertools.combinations(range(n), 3):
        solver.add_clause([-edge_var(c[0], c[1]), -edge_var(c[1], c[2]), -edge_var(c[0], c[2])])

    # No cycles of length 4
    for c in itertools.combinations(range(n), 4):
        for p in itertools.permutations(c):
            if p[0] == min(p) and p[1] < p[3]:
                solver.add_clause([-edge_var(p[0], p[1]), -edge_var(p[1], p[2]), -edge_var(p[2], p[3]), -edge_var(p[3], p[0])])

    # No cycles of length 5
    for c in itertools.combinations(range(n), 5):
        for p in itertools.permutations(c):
            if p[0] == min(p) and p[1] < p[4]:
                solver.add_clause([-edge_var(p[0], p[1]), -edge_var(p[1], p[2]), -edge_var(p[2], p[3]), -edge_var(p[3], p[4]), -edge_var(p[4], p[0])])

    # No cycles of length 6
    for c in itertools.combinations(range(n), 6):
        for p in itertools.permutations(c):
            if p[0] == min(p) and p[1] < p[5]:
                solver.add_clause([-edge_var(p[0], p[1]), -edge_var(p[1], p[2]), -edge_var(p[2], p[3]), -edge_var(p[3], p[4]), -edge_var(p[4], p[5]), -edge_var(p[5], p[0])])

    # At least 37 edges
    edge_vars = [edge_var(i, j) for i in range(n) for j in range(i+1, n)]
    cnf = CardEnc.atleast(lits=edge_vars, bound=37, encoding=EncType.seqcounter)
    for clause in cnf.clauses:
        solver.add_clause(clause)

    print("Solving...")
    if solver.solve():
        print("SAT")
    else:
        print("UNSAT")

solve()

