                s.add(Not(And(edge(i,j), edge(j,l), edge(l,k), edge(k,i))))
                s.add(Not(And(edge(i,k), edge(k,j), edge(j,l), edge(l,i))))

# Instead of adding all C5 and C6, let's just add a few and use a CEGAR loop
print("Starting CEGAR loop")
while True:
    if s.check() == sat:
        m = s.model()
        edges = []
        for i in range(n):
            for j in range(i+1, n):
                if is_true(m[E[i][j]]):
